import React from "react";
import styles from "../styles/cardComponent.css";

export default function Card({name, image, temperament, weightMin, weightMax}) {
  return(
    <div>
        <div className={styles.homeCard}>
        <div>
            <h3>{name}</h3>
            </div>
            <img src={image} alt="img"  width="200" height="150"/>
            <h4>Peso: </h4>
            <div>
              <p>Hola</p>
              {/* <p> Min: {weightMin}/kg - Max: {weightMax}/kg</p> */}
              </div> 
              <p>Chau</p>
            <h4>Temperamento:</h4><p> {temperament}</p>                
        </div>
        <p>aaaaa</p>
    </div>
)
  }
